'use client';

import { BookOpen, FileUp, MoreHorizontal, Pencil, Plus, Trash2 } from 'lucide-react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { useState } from 'react';
import { Button, IconButton } from '@/components/ui/button';
import { Card, CardBody, CardHeader } from '@/components/ui/card';
import { ConfirmDialog, Dialog } from '@/components/ui/dialog';
import { Field } from '@/components/ui/field';
import { FormError } from '@/components/ui/form-error';
import { Input, Textarea } from '@/components/ui/input';
import { LoadMore } from '@/components/ui/load-more';
import { Menu, MenuItem } from '@/components/ui/menu';
import { PageBody, PageHeader } from '@/components/ui/page';
import { EmptyState, ErrorState, LoadingState } from '@/components/ui/states';
import { Table, TBody, Td, Th, THead, Tr } from '@/components/ui/table';
import { useToast } from '@/components/ui/toast';
import type { KnowledgeDocument } from '@/lib/api/types';
import { formatNumber, formatRelative } from '@/lib/format';
import { apiErrorsFor, type FieldErrors } from '@/lib/forms';
import { useSession } from '@/lib/session';
import { useDebounced } from '@/lib/use-debounced';
import { readTextFile, useDocument, useDocuments, useKnowledgeBase, useKnowledgeBaseMutations, usePassageSearch } from './api';
import { formatChars, NameDialog } from './shared';

const MAX_CONTENT = 500_000;

/** Add a document, or open one to read and edit. Text can be typed, pasted or loaded from a .txt / .md / .csv file. */
function DocumentDialog({ baseId, documentId, readOnly, onOpenChange }: { baseId: string; documentId: string | null; readOnly: boolean; onOpenChange: (open: boolean) => void }) {
  const toast = useToast();
  const existing = useDocument(baseId, documentId);
  const mutations = useKnowledgeBaseMutations(baseId);
  const [title, setTitle] = useState<string | null>(null);
  const [content, setContent] = useState<string | null>(null);
  const [sourceName, setSourceName] = useState<string | null>(null);
  const [errors, setErrors] = useState<FieldErrors>({});
  const [busy, setBusy] = useState(false);
  const loading = documentId !== null && existing.isPending;
  const shownTitle = title ?? existing.data?.title ?? '';
  const shownContent = content ?? existing.data?.content ?? '';

  const save = async () => {
    const next: FieldErrors = {};
    if (!shownTitle.trim()) next.title = 'Give the document a title';
    if (!shownContent.trim()) next.content = 'Add the text the assistant should know';
    setErrors(next);
    if (Object.keys(next).length) return;
    setBusy(true);
    try {
      if (documentId) {
        await mutations.updateDocument.mutateAsync({ documentId, body: { ...(title !== null ? { title: title.trim() } : {}), ...(content !== null ? { content } : {}) } });
        toast.success('Document saved', 'Assistants use the new text from their next conversation.');
      } else {
        await mutations.createDocument.mutateAsync({ title: shownTitle.trim(), content: shownContent, sourceName });
        toast.success('Document added');
      }
      onOpenChange(false);
    } catch (error) {
      setErrors(apiErrorsFor(error));
    } finally {
      setBusy(false);
    }
  };

  return (
    <Dialog
      open
      onOpenChange={onOpenChange}
      size="xl"
      title={documentId ? (readOnly ? shownTitle || 'Document' : 'Edit document') : 'Add a document'}
      description={documentId ? undefined : 'Plain text or Markdown. Long documents are split into passages the assistant searches.'}
      footer={
        readOnly ? (
          <Button variant="secondary" onClick={() => onOpenChange(false)}>
            Close
          </Button>
        ) : (
          <>
            <Button variant="secondary" onClick={() => onOpenChange(false)} disabled={busy}>
              Cancel
            </Button>
            <Button variant="primary" loading={busy} disabled={loading} onClick={() => void save()}>
              {documentId ? 'Save document' : 'Add document'}
            </Button>
          </>
        )
      }
    >
      {loading ? (
        <LoadingState label="Loading document…" rows={4} />
      ) : existing.isError ? (
        <ErrorState error={existing.error} title="Could not load this document" onRetry={() => void existing.refetch()} />
      ) : (
        <div className="flex flex-col gap-4">
          <FormError errors={errors} shown={['title', 'content']} />
          {readOnly ? null : (
            <Field label="Title" required error={errors.title}>
              {(props) => <Input {...props} value={shownTitle} maxLength={300} placeholder="Returns and refunds" onChange={(e) => setTitle(e.target.value)} />}
            </Field>
          )}
          {readOnly || documentId ? null : (
            <div className="flex flex-wrap items-center gap-2">
              <label htmlFor="document-file" className="inline-flex h-9 cursor-pointer items-center gap-2 rounded-md border border-control bg-surface px-3 text-sm font-medium text-text hover:bg-surface-2">
                <FileUp aria-hidden="true" className="size-4" />
                Load text from a file
              </label>
              <input
                id="document-file"
                type="file"
                accept=".txt,.md,.markdown,.csv,text/plain,text/markdown,text/csv"
                className="sr-only"
                onChange={async (e) => {
                  const file = e.target.files?.[0];
                  if (!file) return;
                  const read = await readTextFile(file);
                  if ('error' in read) {
                    setErrors({ content: read.error });
                    return;
                  }
                  setContent(read.text);
                  setSourceName(file.name);
                  if (!shownTitle.trim()) setTitle(file.name.replace(/\.[^.]+$/, ''));
                  setErrors({});
                }}
              />
              <span className="text-sm text-muted">{sourceName ?? '.txt, .md or .csv; PDFs and images come later'}</span>
            </div>
          )}
          <Field label="Text" error={errors.content} description={`${formatNumber(shownContent.length)} of ${formatNumber(MAX_CONTENT)} characters`}>
            {(props) => <Textarea {...props} rows={16} value={shownContent} readOnly={readOnly} maxLength={MAX_CONTENT} onChange={(e) => setContent(e.target.value)} />}
          </Field>
        </div>
      )}
    </Dialog>
  );
}

function TestPassageSearch({ baseId }: { baseId: string }) {
  const [q, setQ] = useState('');
  const term = useDebounced(q).trim();
  const search = usePassageSearch(baseId, term, term.length > 0);
  return (
    <Card>
      <CardHeader title="Try the assistant's search" description="The passages a large knowledge base returns for a question during a conversation." />
      <CardBody className="flex flex-col gap-3">
        <div className="max-w-md">
          <label htmlFor="passage-search" className="mb-1.5 block text-sm font-medium text-text">
            Question words
          </label>
          <Input id="passage-search" type="search" placeholder="return refund" value={q} onChange={(e) => setQ(e.target.value)} />
        </div>
        {!term ? null : search.isPending ? (
          <LoadingState label="Searching…" rows={2} />
        ) : search.isError ? (
          <ErrorState error={search.error} title="Search failed" onRetry={() => void search.refetch()} />
        ) : search.data.data.length === 0 ? (
          <p className="text-sm text-muted" role="status">
            No passage matches. The assistant would say it does not have that information.
          </p>
        ) : (
          <ol aria-label="Passages" className="flex flex-col gap-2">
            {search.data.data.map((hit, index) => (
              <li key={`${hit.documentId}-${index}`} className="rounded-md border border-border px-3 py-2">
                <p className="text-xs font-medium text-muted">{hit.title}</p>
                <p className="mt-1 line-clamp-4 text-sm whitespace-pre-line text-text">{hit.text}</p>
              </li>
            ))}
          </ol>
        )}
      </CardBody>
    </Card>
  );
}

export function KnowledgeBaseDetail({ id }: { id: string }) {
  const { can } = useSession();
  const router = useRouter();
  const toast = useToast();
  const base = useKnowledgeBase(id);
  const documents = useDocuments(id);
  const mutations = useKnowledgeBaseMutations(id);
  const canManage = can('knowledge:manage');
  const [dialog, setDialog] = useState<null | { kind: 'document'; documentId: string | null } | { kind: 'rename' } | { kind: 'delete' } | { kind: 'delete-document'; document: KnowledgeDocument }>(null);
  const close = (open: boolean) => (open ? undefined : setDialog(null));

  if (base.isPending) {
    return (
      <PageBody>
        <LoadingState label="Loading knowledge base…" />
      </PageBody>
    );
  }
  if (base.isError) {
    return (
      <PageBody>
        <ErrorState error={base.error} title="Could not load this knowledge base" onRetry={() => void base.refetch()} />
      </PageBody>
    );
  }
  const data = base.data;

  return (
    <PageBody>
      <PageHeader
        breadcrumb={
          <Link href="/knowledge" className="hover:underline">
            Knowledge
          </Link>
        }
        title={data.name}
        description={`${formatNumber(data.documentCount)} documents · ${formatChars(data.charCount)} · used by ${data.assistantCount === 1 ? '1 assistant' : `${data.assistantCount ?? 0} assistants`}${data.description ? ` · ${data.description}` : ''}`}
        actions={
          canManage ? (
            <>
              <Button variant="primary" onClick={() => setDialog({ kind: 'document', documentId: null })}>
                <Plus aria-hidden="true" />
                Add document
              </Button>
              <Menu label="Knowledge base actions" trigger={<IconButton label="Knowledge base actions" icon={<MoreHorizontal />} variant="secondary" size="md" />}>
                <MenuItem onSelect={() => setDialog({ kind: 'rename' })}>
                  <Pencil aria-hidden="true" />
                  Rename
                </MenuItem>
                <MenuItem tone="danger" onSelect={() => setDialog({ kind: 'delete' })}>
                  <Trash2 aria-hidden="true" />
                  Delete knowledge base
                </MenuItem>
              </Menu>
            </>
          ) : null
        }
      />

      <div className="flex flex-col gap-6">
        {documents.isPending ? (
          <LoadingState label="Loading documents…" />
        ) : documents.isError ? (
          <ErrorState error={documents.error} title="Could not load documents" onRetry={() => void documents.refetch()} />
        ) : documents.items.length === 0 ? (
          <EmptyState
            icon={<BookOpen />}
            title="No documents yet"
            description="Add your return policy, delivery terms, payment options or FAQs. Small knowledge bases are given to the assistant whole; larger ones are searched."
            action={
              canManage ? (
                <Button variant="primary" onClick={() => setDialog({ kind: 'document', documentId: null })}>
                  <Plus aria-hidden="true" />
                  Add document
                </Button>
              ) : null
            }
          />
        ) : (
          <>
            <Table label="Documents">
              <THead>
                <Tr>
                  <Th>Title</Th>
                  <Th className="hidden sm:table-cell">Size</Th>
                  <Th className="hidden md:table-cell">Passages</Th>
                  <Th className="hidden md:table-cell">Updated</Th>
                  {canManage ? (
                    <Th className="w-12">
                      <span className="sr-only">Actions</span>
                    </Th>
                  ) : null}
                </Tr>
              </THead>
              <TBody>
                {documents.items.map((doc) => (
                  <Tr key={doc.id}>
                    <Td>
                      <button type="button" onClick={() => setDialog({ kind: 'document', documentId: doc.id })} className="text-left font-medium text-accent-text underline-offset-4 hover:underline">
                        {doc.title}
                      </button>
                      {doc.sourceName ? <p className="text-xs text-muted">{doc.sourceName}</p> : null}
                    </Td>
                    <Td className="hidden text-muted sm:table-cell">{formatChars(doc.charCount)}</Td>
                    <Td className="hidden text-muted tabular-nums md:table-cell">{doc.chunkCount}</Td>
                    <Td className="hidden text-muted md:table-cell">{formatRelative(doc.updatedAt)}</Td>
                    {canManage ? (
                      <Td className="w-12 text-right">
                        <IconButton label={`Delete ${doc.title}`} icon={<Trash2 />} variant="danger-ghost" onClick={() => setDialog({ kind: 'delete-document', document: doc })} />
                      </Td>
                    ) : null}
                  </Tr>
                ))}
              </TBody>
            </Table>
            <LoadMore count={documents.items.length} noun="document" hasNextPage={documents.hasNextPage} isFetchingNextPage={documents.isFetchingNextPage} fetchNextPage={documents.fetchNextPage} />
          </>
        )}
        {data.documentCount > 0 ? <TestPassageSearch baseId={id} /> : null}
      </div>

      {dialog?.kind === 'document' ? <DocumentDialog baseId={id} documentId={dialog.documentId} readOnly={!canManage} onOpenChange={close} /> : null}
      {dialog?.kind === 'rename' ? (
        <NameDialog open onOpenChange={close} title="Rename knowledge base" submitLabel="Save" initial={{ name: data.name, description: data.description }} onSubmit={(value) => mutations.update.mutateAsync(value)} />
      ) : null}
      <ConfirmDialog
        open={dialog?.kind === 'delete'}
        onOpenChange={close}
        title={`Delete ${data.name}?`}
        description={`Its ${formatNumber(data.documentCount)} documents are deleted too. Assistants that use it will answer without it.`}
        confirmLabel="Delete knowledge base"
        onConfirm={async () => {
          try {
            await mutations.remove.mutateAsync();
            toast.success('Knowledge base deleted');
            router.push('/knowledge');
          } catch (error) {
            toast.error('Could not delete the knowledge base', error);
            throw error;
          }
        }}
      />
      <ConfirmDialog
        open={dialog?.kind === 'delete-document'}
        onOpenChange={close}
        title={dialog?.kind === 'delete-document' ? `Delete ${dialog.document.title}?` : 'Delete document?'}
        description="Assistants stop using it from their next conversation."
        confirmLabel="Delete document"
        onConfirm={async () => {
          if (dialog?.kind !== 'delete-document') return;
          try {
            await mutations.removeDocument.mutateAsync(dialog.document.id);
            toast.success('Document deleted');
          } catch (error) {
            toast.error('Could not delete the document', error);
            throw error;
          }
        }}
      />
    </PageBody>
  );
}
